import React from 'react';

import Search from '@pohodnik/icons/svg/Communication/Search';
import { useNavigate, useSearchParams } from 'react-router-dom';

import HikingBaseList from '@apps/Hiking/@components/HikingBaseList';
import Page from '@components/Page';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohInput, { InputSizes, InputTypes } from '@ui-kit/Input';
import PohContainer from '@ui-kit/layout/Container';
import PohList from '@ui-kit/List';
import { showModal } from '@ui-kit/Modal';

import RoutesListItem from './RoutesListItem';
import { getAllRoutes, IRouteListItem } from '../@services/routes.service';

const RoutesList: React.FC = () => {
  const [searchParams] = useSearchParams();
  const [data, setData] = React.useState<IRouteListItem[]>([]);
  const [fetchedData, setFetchedData] = React.useState<IRouteListItem[]>([]);
  const [q] = React.useState(searchParams.get('q') ?? '');
  const [isLoading, setIsLoading] = React.useState(true);
  const navigate = useNavigate();
  React.useEffect(() => {
    getAllRoutes()
      .then((res) => {
        setFetchedData(res);
      })
      .finally(() => setIsLoading(false));
  }, []);

  React.useEffect(() => {
    setData(
      q.length
        ? fetchedData.filter((x) =>
            JSON.stringify(x).toLowerCase().includes(q.toLocaleLowerCase().trim()),
          )
        : fetchedData,
    );
  }, [q, fetchedData]);

  return (
    <Page title="Маршруты">
      <PohBreadcrumbs data={[{ href: '/routes', text: 'Маршруты', active: true }]} />
      <PohContainer>
        <PageHeader
          title="Маршруты"
          center={
            <form className="m-1 w-100 d-flex align-items-center">
              <PohInput
                placeholder="Поиск по маршрутам"
                size={InputSizes.Small}
                type={InputTypes.search}
                name="q"
                defaultValue={q}
              />
              <PohButton icon type="submit" className="ms-1" size={ButtonSize.Small}>
                <Search />
              </PohButton>
            </form>
          }
        >
          <PohButton
            variant={ButtonVariant.Success}
            size={ButtonSize.Small}
            onClick={() => {
              navigate(`/routes/add`);
            }}
          >
            Создать маршрут
          </PohButton>
        </PageHeader>

        {isLoading && <PageLoader />}
        {!data.length && <Empty>Маршрутов не найдено</Empty>}
        {!!data.length && (
          <PohList
            className="mt-2"
            data={data.map((x) => ({
              key: x.id,
              action: true,
              onClick: () => {
                navigate(`/routes/${x.id}`);
              },
              content: (
                <RoutesListItem
                  data={x}
                  onHikingBadgeClick={(d) => {
                    showModal({
                      title: `Походы по маршруту ${d.name}`,
                      children: (close) => (
                        <HikingBaseList
                          list={d.hikingList}
                          onSelect={(s, ev) => {
                            navigate(`/hiking/${s.id}`);
                            !ev.ctrlKey && close();
                          }}
                        />
                      ),
                    });
                  }}
                />
              ),
            }))}
          />
        )}
      </PohContainer>
    </Page>
  );
};
export default RoutesList;
